const cdec=s=>{const a=s.split(',');const P=[];for(let i=0;i+1<a.length;i+=2)P.push([a[i]/8,a[i+1]/8]);return P};
const cbb=P=>{let a=1e9,b=1e9,c=-1e9,d=-1e9;for(const [x,y] of P){if(x<a)a=x;if(y<b)b=y;if(x>c)c=x;if(y>d)d=y}return [a,b,c,d]};
const cArea=P=>{let A=0;for(let i=0;i<P.length;i++){const a=P[i],c=P[(i+1)%P.length];A+=a[0]*c[1]-c[0]*a[1]}return A};
