DECOR_DRAW.cmat=(g,d,x,y,w,h)=>{g.save();g.translate(x+w/2,y+h/2);shadow(g,0,h/2-1,w/2,2);rr(g,-w/2,-h/2,w,h,3,d.c1);g.fillStyle=d.c2;for(let k=-w/2+4;k<w/2;k+=8)g.fillRect(k,-h/2,4,h);
  rr(g,-w/2,-h/2,w,h,3);g.strokeStyle='rgba(255,255,255,.7)';g.lineWidth=1;g.stroke();(MAT_FOOD_DRAW[d.food]||MAT_FOOD_DRAW.kimbap)(g);g.restore()};
function cNearFree(ax,ay,cls,R){let best=null,bd=1e9;for(let dy=-R;dy<=R;dy+=.5)for(let dx=-R;dx<=R;dx+=.5){const x=ax+dx,y=ay+dy;if(!cFree(x,y)||!cReach(x,y))continue;if(cls&&!cls.includes(cCls(x,y)))continue;const d=Math.hypot(dx,dy);if(d<bd){bd=d;best=[x,y]}}return best}
function cMatSpot(ax,ay){for(let R=1;R<=14;R+=2){for(let dy=-R;dy<=R;dy+=1)for(let dx=-R;dx<=R;dx+=1){const x=Math.round(ax+dx),y=Math.round(ay+dy);let ok=true;
  for(let yy=y-1.2;yy<=y+3.4&&ok;yy+=.5)for(let xx=x-1;xx<=x+5&&ok;xx+=.5)if(!cFree(xx,yy)||cCls(xx,yy)!==2)ok=false;if(ok)return [x,y]}}return null}
const CPICNIC=[];
[[150.7,114,'chicken','#F3A6A6'],[141,113,'kimbap','#8FC1E3'],[158,116,'pizza','#F5D36E'],[136.5,47.5,'jjamak','#A8D5A0'],[149,47,'chicken','#F3A6A6']].forEach(([ax,ay,food,c1])=>{const s=cMatSpot(ax,ay);if(!s)return;
  const m={t:'cmat',x:s[0],y:s[1]+.3,w:4,h:2,flat:true,walk:true,food,c1,c2:'rgba(255,255,255,.45)'};if(CPICNIC.some(o=>Math.abs(o.x-m.x)<6&&Math.abs(o.y-m.y)<4))return;CPICNIC.push(m);CDEC.push(m)});
